# File: feature-flow.sh — the everyday FEATURE BRANCH + PR workflow.

# 1. Start from an up-to-date main.
git checkout main
git pull origin main

# 2. Create a SHORT-LIVED, descriptively named feature branch.
git checkout -b feature/loan-interest-calculation

# 3. Do the work (add InterestCalculator.java), commit in small logical steps.
git add src/main/java/com/bank/payments/InterestCalculator.java
git commit -m "PAY-412 add simple interest calculator for loans"
git add src/test/java/com/bank/payments/InterestCalculatorTest.java
git commit -m "PAY-412 add tests for interest calculator"

# 4. Keep the branch current while main moves on (small, frequent integration).
git fetch origin
git rebase origin/main        # or: git merge origin/main

# 5. Push the branch and open a PR targeting main.
git push -u origin feature/loan-interest-calculation
# Open PR in GitHub/GitLab -> triggers CI (build+tests) + human review.

# 6. After approvals + green CI, merge (squash keeps main history clean).
#    Done via the PR button; locally you then clean up:
git checkout main
git pull origin main
git branch -d feature/loan-interest-calculation   # delete the short-lived branch
```

```bash
# File: hotfix-flow.sh — URGENT production fix path.

# 1. Cut the hotfix branch straight from the PRODUCTION release point (a tag).
git checkout -b hotfix/double-charge-fix v1.4.0

# 2. Make the SMALLEST possible fix and commit.
git add src/main/java/com/bank/payments/InterestCalculator.java
git commit -m "PAY-999 hotfix: stop double-applying interest on retry"

# 3. Expedited review, then tag and deploy the patched release.
git tag v1.4.1
git push origin hotfix/double-charge-fix --tags

# 4. CRUCIAL: merge the SAME fix back into main so it never regresses.
git checkout main
git pull origin main
git merge hotfix/double-charge-fix
git push origin main

# 5. Clean up the hotfix branch.
git branch -d hotfix/double-charge-fix
```

