// ─── File: src/main/java/com/bank/payments/InterestCalculator.java ───
package com.bank.payments;

import java.math.BigDecimal;
import java.math.RoundingMode;

// Added by the FEATURE branch, corrected by the HOTFIX branch.
public class InterestCalculator {

    // Compute simple interest once per calculation. The hotfix ensures a
    // retried request does NOT apply interest twice (idempotency guard).
    public BigDecimal interest(BigDecimal principal, BigDecimal ratePercent,
                               int years, boolean alreadyApplied) {
        if (alreadyApplied) {
            // HOTFIX PAY-999: on a retry, return zero instead of charging again.
            return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_UP);
        }
        BigDecimal rate = ratePercent.divide(new BigDecimal("100"));
        return principal.multiply(rate).multiply(new BigDecimal(years))
                        .setScale(2, RoundingMode.HALF_UP);
    }
}
