package com.bank.payments;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;

class InterestCalculatorTest {

    private final InterestCalculator calc = new InterestCalculator();

    @Test
    void firstApplicationCharges() {
        // Rajesh: 1,000,000 at 8% for 2 years = 160000.00
        assertEquals(new BigDecimal("160000.00"),
                calc.interest(new BigDecimal("1000000"), new BigDecimal("8"), 2, false));
    }

    @Test
    void retryDoesNotDoubleCharge() {
        // The hotfix: already applied -> 0.00, not another 160000.
        assertEquals(new BigDecimal("0.00"),
                calc.interest(new BigDecimal("1000000"), new BigDecimal("8"), 2, true));
    }
}
